package com.github.uscexp.jfilework.ui.javafx.action;

import java.util.Map;

/**
 * UI callback for executing a command resolved from configuration.
 */
@FunctionalInterface
public interface CommandExecutionHandler {

    void execute(String commandId, Map<String, String> params, String actionLabel);
}

package com.github.uscexp.jfilework.ui.javafx.action;

import java.util.List;
import java.util.Map;

/**
 * Runtime action model generated from configuration.
 */
public record ConfiguredAction(
        String id,
        String label,
        String commandId,
        Map<String, String> params,
        String shortcut,
        List<String> placement,
        boolean enabled
) {
}

package com.github.uscexp.jfilework.ui.javafx.action;

import javafx.scene.Scene;
import javafx.scene.input.KeyCombination;
import javafx.scene.input.KeyEvent;

import java.util.List;

/**
 * Registers and dispatches configured key bindings.
 */
public class KeyBindingService {

    public void bind(Scene scene, List<ConfiguredAction> actions, CommandExecutionHandler handler) {
        scene.addEventFilter(KeyEvent.KEY_PRESSED, event -> {
            for (ConfiguredAction action : actions) {
                if (!action.enabled() || action.shortcut() == null || action.shortcut().isBlank()) {
                    continue;
                }
                KeyCombination keyCombination;
                try {
                    keyCombination = KeyCombination.keyCombination(action.shortcut());
                } catch (IllegalArgumentException ignored) {
                    continue;
                }
                if (keyCombination.match(event)) {
                    handler.execute(action.commandId(), action.params(), action.label());
                    event.consume();
                    break;
                }
            }
        });
    }
}

package com.github.uscexp.jfilework.ui.javafx.action;

import javafx.scene.control.Menu;
import javafx.scene.control.MenuItem;
import javafx.scene.control.SeparatorMenuItem;

import java.util.List;

/**
 * Builds menu entries from configured actions.
 */
public class MenuBuilder {

    public void build(Menu fileMenu, Menu toolsMenu, List<ConfiguredAction> actions, CommandExecutionHandler handler) {
        removeDynamicItems(fileMenu);
        removeDynamicItems(toolsMenu);

        addItems(fileMenu, actions, "menu.file", handler);
        addItems(toolsMenu, actions, "menu.tools", handler);
    }

    private void addItems(Menu menu, List<ConfiguredAction> actions, String placement, CommandExecutionHandler handler) {
        boolean hasStaticItems = !menu.getItems().isEmpty();
        int inserted = 0;

        for (ConfiguredAction action : actions) {
            if (!action.placement().contains(placement)) {
                continue;
            }

            MenuItem item = new MenuItem(action.label());
            item.setId("action-" + action.id());
            item.getProperties().put("dynamicAction", Boolean.TRUE);
            item.setDisable(!action.enabled());
            item.setOnAction(event -> handler.execute(action.commandId(), action.params(), action.label()));
            menu.getItems().add(0, item);
            inserted++;
        }

        if (hasStaticItems && inserted > 0 && !menu.getItems().isEmpty()) {
            boolean alreadySeparated = menu.getItems().stream().findFirst().orElse(null) instanceof SeparatorMenuItem;
            if (!alreadySeparated) {
                SeparatorMenuItem separator = new SeparatorMenuItem();
                separator.getProperties().put("dynamicAction", Boolean.TRUE);
                menu.getItems().add(inserted, separator);
            }
        }
    }

    private static void removeDynamicItems(Menu menu) {
        menu.getItems().removeIf(item -> Boolean.TRUE.equals(item.getProperties().get("dynamicAction")));
    }
}

package com.github.uscexp.jfilework.ui.javafx.action;

import com.github.uscexp.jfilework.core.command.CommandContext;

import java.nio.file.Path;
import java.util.HashMap;
import java.util.Map;
import java.util.stream.Collectors;

/**
 * Resolves simple placeholders used by command parameter templates.
 */
public class ParamTemplateEngine {

    public Map<String, String> resolve(Map<String, String> templateParams, CommandContext context) {
        Map<String, String> resolved = new HashMap<>();
        if (templateParams == null) {
            return resolved;
        }

        for (Map.Entry<String, String> entry : templateParams.entrySet()) {
            resolved.put(entry.getKey(), resolveValue(entry.getValue(), context));
        }
        return resolved;
    }

    private String resolveValue(String value, CommandContext context) {
        if (value == null) {
            return "";
        }

        String result = value;
        result = result.replace("${activePane.path}", context.activeDirectory().toString());
        result = result.replace("${inactivePane.path}", context.inactiveDirectory().toString());
        result = result.replace("${selection.paths}", context.selection().paths().stream()
                .map(Path::toString)
                .collect(Collectors.joining(" ")));
        return result;
    }
}

package com.github.uscexp.jfilework.ui.javafx.action;

import javafx.scene.control.Button;
import javafx.scene.control.ToolBar;

import java.util.List;

/**
 * Builds toolbar buttons from configured actions.
 */
public class ToolbarBuilder {

    public void build(ToolBar toolBar, List<ConfiguredAction> actions, CommandExecutionHandler handler) {
        toolBar.getItems().clear();

        actions.stream()
                .filter(action -> action.placement().contains("toolbar.main"))
                .forEach(action -> {
                    Button button = new Button(action.label());
                    button.setId("action-" + action.id());
                    button.setDisable(!action.enabled());
                    button.setOnAction(event -> handler.execute(action.commandId(), action.params(), action.label()));
                    toolBar.getItems().add(button);
                });
    }
}

package com.github.uscexp.jfilework.ui.javafx.action;

import com.github.uscexp.jfilework.core.command.CommandRegistry;
import com.github.uscexp.jfilework.core.config.ActionConfig;
import com.github.uscexp.jfilework.core.config.AppConfig;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

import java.util.List;
import java.util.Map;

/**
 * Converts configuration entries into runtime actions and marks unknown commands as disabled.
 */
public class UiActionMapper {

    private static final Logger log = LoggerFactory.getLogger(UiActionMapper.class);

    private final CommandRegistry commandRegistry;

    public UiActionMapper(CommandRegistry commandRegistry) {
        this.commandRegistry = commandRegistry;
    }

    public List<ConfiguredAction> map(AppConfig appConfig) {
        if (appConfig == null || appConfig.actions() == null) {
            return List.of();
        }

        return appConfig.actions().stream()
                .map(this::mapAction)
                .toList();
    }

    private ConfiguredAction mapAction(ActionConfig actionConfig) {
        boolean available = commandRegistry.findById(actionConfig.commandId()).isPresent();
        if (!available) {
            log.warn("Action '{}' references unknown command '{}'", actionConfig.id(), actionConfig.commandId());
        }

        return new ConfiguredAction(
                actionConfig.id(),
                actionConfig.label(),
                actionConfig.commandId(),
                actionConfig.params() == null ? Map.of() : actionConfig.params(),
                actionConfig.shortcut() == null ? "" : actionConfig.shortcut(),
                actionConfig.placement() == null ? List.of() : actionConfig.placement(),
                available
        );
    }
}

package com.github.uscexp.jfilework.ui.javafx.controller;

import com.github.uscexp.jfilework.core.command.CancellationToken;
import com.github.uscexp.jfilework.core.command.Command;
import com.github.uscexp.jfilework.core.command.CommandContext;
import com.github.uscexp.jfilework.core.command.CommandExecutor;
import com.github.uscexp.jfilework.core.command.CommandRegistry;
import com.github.uscexp.jfilework.core.command.CommandResult;
import com.github.uscexp.jfilework.core.command.ProgressSink;
import com.github.uscexp.jfilework.core.command.SelectionSnapshot;
import com.github.uscexp.jfilework.core.command.builtin.CopyCommand;
import com.github.uscexp.jfilework.core.command.builtin.DeleteCommand;
import com.github.uscexp.jfilework.core.command.builtin.MkdirCommand;
import com.github.uscexp.jfilework.core.command.builtin.MoveCommand;
import com.github.uscexp.jfilework.core.command.builtin.RenameCommand;
import com.github.uscexp.jfilework.core.fs.FileService;
import com.github.uscexp.jfilework.core.fs.LocalFileService;
import com.github.uscexp.jfilework.ui.javafx.model.ActivePaneTracker;
import javafx.application.Platform;
import javafx.fxml.FXML;
import javafx.fxml.FXMLLoader;
import javafx.scene.Node;
import javafx.scene.Parent;
import javafx.scene.control.Alert;
import javafx.scene.control.ButtonBar;
import javafx.scene.control.ButtonType;
import javafx.scene.control.Label;
import javafx.scene.control.MenuBar;
import javafx.scene.control.SplitPane;
import javafx.scene.control.TextInputDialog;
import javafx.scene.control.ToolBar;
import javafx.scene.input.KeyCode;
import javafx.scene.input.KeyEvent;
import javafx.scene.layout.VBox;
import javafx.stage.Stage;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

import java.io.IOException;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.List;
import java.util.Map;
import java.util.Optional;
import java.util.concurrent.CompletableFuture;

/**
 * Controller for the main application window (main-window.fxml).
 */
public class MainWindowController {

    private static final Logger log = LoggerFactory.getLogger(MainWindowController.class);

    @FXML private MenuBar menuBar;
    @FXML private ToolBar toolBar;
    @FXML private SplitPane splitPane;
    @FXML private VBox leftPane;
    @FXML private VBox rightPane;
    @FXML private Label statusLabel;

    private final FileService fileService = new LocalFileService();
    private final ActivePaneTracker activePaneTracker = new ActivePaneTracker();
    private final CommandRegistry commandRegistry = new CommandRegistry();
    private final CommandExecutor commandExecutor = new CommandExecutor();
    private final StatusBarController statusBarController = new StatusBarController();

    private FilePaneController leftPaneController;
    private FilePaneController rightPaneController;

    @FXML
    public void initialize() {
        statusBarController.bind(statusLabel);
        registerBuiltInCommands();

        try {
            leftPaneController = mountFilePane(leftPane, "left", "Left pane");
            rightPaneController = mountFilePane(rightPane, "right", "Right pane");

            Path leftStartPath = resolveStartPath("jfilework.leftStartPath");
            Path rightStartPath = resolveStartPath("jfilework.rightStartPath");

            leftPaneController.navigateTo(leftStartPath);
            rightPaneController.navigateTo(rightStartPath);

            statusBarController.showMessage("Ready");
            log.info("Main window initialised with left={} and right={}", leftStartPath, rightStartPath);
        } catch (IOException e) {
            log.error("Cannot initialise file panes", e);
            statusBarController.showMessage("Cannot initialize UI: " + e.getMessage());
        }

        splitPane.sceneProperty().addListener((obs, oldScene, newScene) -> {
            if (newScene != null) {
                newScene.addEventFilter(KeyEvent.KEY_PRESSED, this::onGlobalKeyPressed);
            }
        });
    }

    // -------------------------------------------------------------------------
    // Menu: File
    // -------------------------------------------------------------------------

    @FXML
    private void onExit() {
        if (leftPaneController != null) {
            leftPaneController.stopWatching();
        }
        if (rightPaneController != null) {
            rightPaneController.stopWatching();
        }
        commandExecutor.close();
        Platform.exit();
    }

    @FXML
    private void onCopy() {
        executeCommand("file.copy", Map.of());
    }

    @FXML
    private void onMove() {
        executeCommand("file.move", Map.of());
    }

    @FXML
    private void onMkdir() {
        TextInputDialog dialog = new TextInputDialog();
        dialog.setTitle("Create Folder");
        dialog.setHeaderText("Create folder in active pane");
        dialog.setContentText("Folder name:");
        Optional<String> value = dialog.showAndWait();
        value.ifPresent(name -> executeCommand("file.mkdir", Map.of("name", name)));
    }

    @FXML
    private void onDelete() {
        ButtonType deleteButton = new ButtonType("Delete", ButtonBar.ButtonData.OK_DONE);
        ButtonType cancelButton = new ButtonType("Cancel", ButtonBar.ButtonData.CANCEL_CLOSE);
        Alert alert = new Alert(Alert.AlertType.CONFIRMATION,
                "Delete selected files?",
                deleteButton,
                cancelButton);
        alert.setTitle("Delete");
        alert.setHeaderText("Confirm delete");
        Optional<ButtonType> result = alert.showAndWait();
        if (result.isPresent() && result.get().getButtonData() == ButtonBar.ButtonData.OK_DONE) {
            executeCommand("file.delete", Map.of());
        } else {
            statusBarController.showMessage("Delete cancelled.");
        }
    }

    @FXML
    private void onRename() {
        TextInputDialog dialog = new TextInputDialog();
        dialog.setTitle("Rename");
        dialog.setHeaderText("Rename selected file/folder");
        dialog.setContentText("New name:");
        Optional<String> value = dialog.showAndWait();
        value.ifPresent(name -> executeCommand("file.rename", Map.of("name", name)));
    }

    // -------------------------------------------------------------------------
    // Menu: View
    // -------------------------------------------------------------------------

    @FXML
    private void onPreferences() {
        statusBarController.showMessage("Preferences are available in M3");
    }

    // -------------------------------------------------------------------------
    // Menu: Help
    // -------------------------------------------------------------------------

    @FXML
    private void onAbout() {
        Alert alert = new Alert(Alert.AlertType.INFORMATION);
        alert.setTitle("About jFileWork");
        alert.setHeaderText("jFileWork  v0.0.1-Alpha");
        alert.setContentText("Dual-pane file manager built with Java 26 and JavaFX 23.");
        alert.showAndWait();
    }

    private void registerBuiltInCommands() {
        commandRegistry.register(new CopyCommand());
        commandRegistry.register(new MoveCommand());
        commandRegistry.register(new MkdirCommand());
        commandRegistry.register(new DeleteCommand());
        commandRegistry.register(new RenameCommand());
    }

    private void onGlobalKeyPressed(KeyEvent event) {
        if (event.getCode() == KeyCode.F5) {
            onCopy();
            event.consume();
        } else if (event.getCode() == KeyCode.F6) {
            onMove();
            event.consume();
        } else if (event.getCode() == KeyCode.F7) {
            onMkdir();
            event.consume();
        } else if (event.getCode() == KeyCode.F8) {
            onDelete();
            event.consume();
        } else if (event.getCode() == KeyCode.F2) {
            onRename();
            event.consume();
        }
    }

    private void executeCommand(String commandId, Map<String, String> params) {
        Optional<Command> optionalCommand = commandRegistry.findById(commandId);
        if (optionalCommand.isEmpty()) {
            statusBarController.showMessage("Unknown command: " + commandId);
            return;
        }

        CommandContext context = buildContext();
        if (context == null) {
            return;
        }

        Stage owner = statusLabel.getScene() == null ? null : (Stage) statusLabel.getScene().getWindow();
        ProgressDialogController progressDialog = owner == null
                ? null
                : new ProgressDialogController(owner, context.cancellationToken(), "Running: " + commandId);

        if (progressDialog != null) {
            progressDialog.show();
        }

        Command wrapped = wrapWithArtificialDelay(optionalCommand.get());
        CommandContext instrumentedContext = new CommandContext(
                context.activeDirectory(),
                context.inactiveDirectory(),
                context.selection(),
                context.cancellationToken(),
                new ProgressSink() {
                    @Override
                    public void onProgress(String label, long completedWork, long totalWork) {
                        if (progressDialog != null) {
                            progressDialog.setMessage(label + " " + completedWork + "/" + totalWork);
                        }
                    }
                }
        );

        CompletableFuture<CommandResult> future = commandExecutor.execute(wrapped, instrumentedContext, params);
        future.thenAccept(result -> Platform.runLater(() -> {
            if (progressDialog != null) {
                progressDialog.close();
            }
            leftPaneController.refreshCurrentDirectoryView();
            rightPaneController.refreshCurrentDirectoryView();
            statusBarController.showMessage(result.message());
        }));
    }

    private Command wrapWithArtificialDelay(Command delegate) {
        String rawDelay = System.getProperty("jfilework.command.artificialDelayMs", "0");
        long delayMillis;
        try {
            delayMillis = Long.parseLong(rawDelay);
        } catch (NumberFormatException ignored) {
            delayMillis = 0L;
        }

        if (delayMillis <= 0L) {
            return delegate;
        }

        final long finalDelayMillis = delayMillis;
        return new Command() {
            @Override
            public String id() {
                return delegate.id();
            }

            @Override
            public boolean canExecute(CommandContext context) {
                return delegate.canExecute(context);
            }

            @Override
            public CommandResult execute(CommandContext context, Map<String, String> params) throws Exception {
                Thread.sleep(finalDelayMillis);
                return delegate.execute(context, params);
            }
        };
    }

    private CommandContext buildContext() {
        FilePaneController active = activePaneTracker.getActivePane() == ActivePaneTracker.PaneSide.LEFT
                ? leftPaneController
                : rightPaneController;
        FilePaneController inactive = activePaneTracker.getActivePane() == ActivePaneTracker.PaneSide.LEFT
                ? rightPaneController
                : leftPaneController;

        if (active == null || inactive == null) {
            statusBarController.showMessage("Panes are not ready yet.");
            return null;
        }

        Path activePath = active.getCurrentPath();
        Path inactivePath = inactive.getCurrentPath();
        if (activePath == null || inactivePath == null) {
            statusBarController.showMessage("Please navigate both panes first.");
            return null;
        }

        List<Path> selection = active.getSelectedPathsForOperations();
        return new CommandContext(
                activePath,
                inactivePath,
                new SelectionSnapshot(selection),
                new CancellationToken(),
                ProgressSink.NO_OP
        );
    }

    private FilePaneController mountFilePane(VBox target, String paneId, String title) throws IOException {
        FXMLLoader loader = new FXMLLoader(getClass().getResource("/com/github/uscexp/jfilework/ui/javafx/file-pane.fxml"));
        Parent paneRoot = loader.load();
        FilePaneController controller = loader.getController();
        controller.configure(paneId, title, fileService, this::updateStatus);

        target.getChildren().setAll(paneRoot);
        target.focusedProperty().addListener((obs, oldV, focused) -> {
            if (focused) {
                activePaneTracker.setActivePane("left".equals(paneId)
                        ? ActivePaneTracker.PaneSide.LEFT
                        : ActivePaneTracker.PaneSide.RIGHT);
                statusBarController.showMessage("Active pane: " + activePaneTracker.getActivePane());
            }
        });

        Node table = controller.getFileTable();
        table.focusedProperty().addListener((obs, oldV, focused) -> {
            if (focused) {
                activePaneTracker.setActivePane("left".equals(paneId)
                        ? ActivePaneTracker.PaneSide.LEFT
                        : ActivePaneTracker.PaneSide.RIGHT);
            }
        });

        return controller;
    }

    private Path resolveStartPath(String propertyKey) {
        String configuredPath = System.getProperty(propertyKey);
        if (configuredPath != null && !configuredPath.isBlank()) {
            Path path = Paths.get(configuredPath.trim());
            if (fileService.exists(path) && fileService.isDirectory(path)) {
                return path;
            }
            log.warn("Configured start path '{}' is invalid for {}", configuredPath, propertyKey);
        }

        return Paths.get(System.getProperty("user.home"));
    }

    private void updateStatus(String message) {
        statusBarController.showMessage(message);
    }
}

package com.github.uscexp.jfilework.ui.javafx.controller;

import com.github.uscexp.jfilework.core.command.CancellationToken;
import com.github.uscexp.jfilework.core.command.Command;
import com.github.uscexp.jfilework.core.command.CommandContext;
import com.github.uscexp.jfilework.core.command.CommandExecutor;
import com.github.uscexp.jfilework.core.command.CommandRegistry;
import com.github.uscexp.jfilework.core.command.CommandResult;
import com.github.uscexp.jfilework.core.command.ProgressSink;
import com.github.uscexp.jfilework.core.command.SelectionSnapshot;
import com.github.uscexp.jfilework.core.command.builtin.CopyCommand;
import com.github.uscexp.jfilework.core.command.builtin.DeleteCommand;
import com.github.uscexp.jfilework.core.command.builtin.MkdirCommand;
import com.github.uscexp.jfilework.core.command.builtin.MoveCommand;
import com.github.uscexp.jfilework.core.command.builtin.RenameCommand;
import com.github.uscexp.jfilework.core.config.AppConfig;
import com.github.uscexp.jfilework.core.config.ConfigService;
import com.github.uscexp.jfilework.core.fs.FileService;
import com.github.uscexp.jfilework.core.fs.LocalFileService;
import com.github.uscexp.jfilework.ui.javafx.action.CommandExecutionHandler;
import com.github.uscexp.jfilework.ui.javafx.action.ConfiguredAction;
import com.github.uscexp.jfilework.ui.javafx.action.KeyBindingService;
import com.github.uscexp.jfilework.ui.javafx.action.MenuBuilder;
import com.github.uscexp.jfilework.ui.javafx.action.ParamTemplateEngine;
import com.github.uscexp.jfilework.ui.javafx.action.ToolbarBuilder;
import com.github.uscexp.jfilework.ui.javafx.action.UiActionMapper;
import com.github.uscexp.jfilework.ui.javafx.model.ActivePaneTracker;
import javafx.application.Platform;
import javafx.fxml.FXML;
import javafx.fxml.FXMLLoader;
import javafx.scene.Node;
import javafx.scene.Parent;
import javafx.scene.control.Alert;
import javafx.scene.control.ButtonBar;
import javafx.scene.control.ButtonType;
import javafx.scene.control.Label;
import javafx.scene.control.Menu;
import javafx.scene.control.MenuBar;
import javafx.scene.control.SplitPane;
import javafx.scene.control.TextInputDialog;
import javafx.scene.control.ToolBar;
import javafx.scene.layout.VBox;
import javafx.stage.Stage;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

import java.io.IOException;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Optional;
import java.util.concurrent.CompletableFuture;

/**
 * Controller for the main application window (main-window.fxml).
 */
public class MainWindowController {

    private static final Logger log = LoggerFactory.getLogger(MainWindowController.class);

    @FXML private MenuBar menuBar;
    @FXML private Menu fileMenu;
    @FXML private Menu toolsMenu;
    @FXML private ToolBar toolBar;
    @FXML private SplitPane splitPane;
    @FXML private VBox leftPane;
    @FXML private VBox rightPane;
    @FXML private Label statusLabel;

    private final FileService fileService = new LocalFileService();
    private final ActivePaneTracker activePaneTracker = new ActivePaneTracker();
    private final CommandRegistry commandRegistry = new CommandRegistry();
    private final CommandExecutor commandExecutor = new CommandExecutor();
    private final StatusBarController statusBarController = new StatusBarController();
    private final ConfigService configService = new ConfigService();
    private final ParamTemplateEngine paramTemplateEngine = new ParamTemplateEngine();
    private final KeyBindingService keyBindingService = new KeyBindingService();
    private final ToolbarBuilder toolbarBuilder = new ToolbarBuilder();
    private final MenuBuilder menuBuilder = new MenuBuilder();

    private FilePaneController leftPaneController;
    private FilePaneController rightPaneController;
    private List<ConfiguredAction> configuredActions = List.of();
    private boolean keyBindingsInstalled;

    @FXML
    public void initialize() {
        statusBarController.bind(statusLabel);
        registerBuiltInCommands();
        AppConfig appConfig = configService.load();

        try {
            leftPaneController = mountFilePane(leftPane, "left", "Left pane");
            rightPaneController = mountFilePane(rightPane, "right", "Right pane");

            Path leftStartPath = resolveStartPath("jfilework.leftStartPath", appConfig.ui().leftStartPath());
            Path rightStartPath = resolveStartPath("jfilework.rightStartPath", appConfig.ui().rightStartPath());

            leftPaneController.navigateTo(leftStartPath);
            rightPaneController.navigateTo(rightStartPath);

            configuredActions = new UiActionMapper(commandRegistry).map(appConfig);
            CommandExecutionHandler handler = this::executeConfiguredCommand;
            toolbarBuilder.build(toolBar, configuredActions, handler);
            menuBuilder.build(fileMenu, toolsMenu, configuredActions, handler);

            statusBarController.showMessage("Ready");
            log.info("Main window initialised with left={} and right={}", leftStartPath, rightStartPath);
        } catch (IOException e) {
            log.error("Cannot initialise file panes", e);
            statusBarController.showMessage("Cannot initialize UI: " + e.getMessage());
        }

        splitPane.sceneProperty().addListener((obs, oldScene, newScene) -> {
            if (newScene != null && !keyBindingsInstalled) {
                keyBindingService.bind(newScene, configuredActions, this::executeConfiguredCommand);
                keyBindingsInstalled = true;
            }
        });
    }

    // -------------------------------------------------------------------------
    // Menu: File
    // -------------------------------------------------------------------------

    @FXML
    private void onExit() {
        if (leftPaneController != null) {
            leftPaneController.stopWatching();
        }
        if (rightPaneController != null) {
            rightPaneController.stopWatching();
        }
        commandExecutor.close();
        Platform.exit();
    }

    private boolean confirmDelete() {
        ButtonType deleteButton = new ButtonType("Delete", ButtonBar.ButtonData.OK_DONE);
        ButtonType cancelButton = new ButtonType("Cancel", ButtonBar.ButtonData.CANCEL_CLOSE);
        Alert alert = new Alert(Alert.AlertType.CONFIRMATION,
                "Delete selected files?",
                deleteButton,
                cancelButton);
        alert.setTitle("Delete");
        alert.setHeaderText("Confirm delete");
        Optional<ButtonType> result = alert.showAndWait();
        return result.isPresent() && result.get().getButtonData() == ButtonBar.ButtonData.OK_DONE;
    }

    // -------------------------------------------------------------------------
    // Menu: View
    // -------------------------------------------------------------------------

    @FXML
    private void onPreferences() {
        statusBarController.showMessage("Preferences are available in M3");
    }

    // -------------------------------------------------------------------------
    // Menu: Help
    // -------------------------------------------------------------------------

    @FXML
    private void onAbout() {
        Alert alert = new Alert(Alert.AlertType.INFORMATION);
        alert.setTitle("About jFileWork");
        alert.setHeaderText("jFileWork  v0.0.1-Alpha");
        alert.setContentText("Dual-pane file manager built with Java 26 and JavaFX 23.");
        alert.showAndWait();
    }

    private void registerBuiltInCommands() {
        commandRegistry.register(new CopyCommand());
        commandRegistry.register(new MoveCommand());
        commandRegistry.register(new MkdirCommand());
        commandRegistry.register(new DeleteCommand());
        commandRegistry.register(new RenameCommand());
    }

    private void executeConfiguredCommand(String commandId, Map<String, String> params, String actionLabel) {
        if ("file.delete".equals(commandId) && !confirmDelete()) {
            statusBarController.showMessage("Delete cancelled.");
            return;
        }

        executeCommand(commandId, params, actionLabel);
    }

    private void executeCommand(String commandId, Map<String, String> params, String actionLabel) {
        Optional<Command> optionalCommand = commandRegistry.findById(commandId);
        if (optionalCommand.isEmpty()) {
            statusBarController.showMessage("Unknown command: " + commandId);
            return;
        }

        CommandContext context = buildContext();
        if (context == null) {
            return;
        }

        Map<String, String> resolvedParams = resolveActionParameters(params, context, actionLabel);
        if (resolvedParams == null) {
            statusBarController.showMessage(actionLabel + " cancelled.");
            return;
        }

        Stage owner = statusLabel.getScene() == null ? null : (Stage) statusLabel.getScene().getWindow();
        ProgressDialogController progressDialog = owner == null
                ? null
                : new ProgressDialogController(owner, context.cancellationToken(), "Running: " + commandId);

        if (progressDialog != null) {
            progressDialog.show();
        }

        Command wrapped = wrapWithArtificialDelay(optionalCommand.get());
        CommandContext instrumentedContext = new CommandContext(
                context.activeDirectory(),
                context.inactiveDirectory(),
                context.selection(),
                context.cancellationToken(),
                new ProgressSink() {
                    @Override
                    public void onProgress(String label, long completedWork, long totalWork) {
                        if (progressDialog != null) {
                            progressDialog.setMessage(label + " " + completedWork + "/" + totalWork);
                        }
                    }
                }
        );

        CompletableFuture<CommandResult> future = commandExecutor.execute(wrapped, instrumentedContext, resolvedParams);
        future.thenAccept(result -> Platform.runLater(() -> {
            if (progressDialog != null) {
                progressDialog.close();
            }
            leftPaneController.refreshCurrentDirectoryView();
            rightPaneController.refreshCurrentDirectoryView();
            statusBarController.showMessage(result.message());
        }));
    }

    private Command wrapWithArtificialDelay(Command delegate) {
        String rawDelay = System.getProperty("jfilework.command.artificialDelayMs", "0");
        long delayMillis;
        try {
            delayMillis = Long.parseLong(rawDelay);
        } catch (NumberFormatException ignored) {
            delayMillis = 0L;
        }

        if (delayMillis <= 0L) {
            return delegate;
        }

        final long finalDelayMillis = delayMillis;
        return new Command() {
            @Override
            public String id() {
                return delegate.id();
            }

            @Override
            public boolean canExecute(CommandContext context) {
                return delegate.canExecute(context);
            }

            @Override
            public CommandResult execute(CommandContext context, Map<String, String> params) throws Exception {
                Thread.sleep(finalDelayMillis);
                return delegate.execute(context, params);
            }
        };
    }

    private Map<String, String> resolveActionParameters(Map<String, String> params, CommandContext context, String actionLabel) {
        Map<String, String> resolved = paramTemplateEngine.resolve(params, context);
        Map<String, String> finalParams = new HashMap<>();
        for (Map.Entry<String, String> entry : resolved.entrySet()) {
            String value = entry.getValue();
            if (value != null && value.startsWith("${prompt:") && value.endsWith("}")) {
                String question = value.substring("${prompt:".length(), value.length() - 1).trim();
                String promptLabel = question.isBlank() ? entry.getKey() : question;

                TextInputDialog dialog = new TextInputDialog();
                dialog.setTitle(actionLabel);
                dialog.setHeaderText(actionLabel);
                dialog.setContentText(promptLabel + ":");
                Optional<String> userInput = dialog.showAndWait();
                if (userInput.isEmpty()) {
                    return null;
                }
                finalParams.put(entry.getKey(), userInput.get().trim());
            } else {
                finalParams.put(entry.getKey(), value);
            }
        }
        return finalParams;
    }

    private CommandContext buildContext() {
        FilePaneController active = activePaneTracker.getActivePane() == ActivePaneTracker.PaneSide.LEFT
                ? leftPaneController
                : rightPaneController;
        FilePaneController inactive = activePaneTracker.getActivePane() == ActivePaneTracker.PaneSide.LEFT
                ? rightPaneController
                : leftPaneController;

        if (active == null || inactive == null) {
            statusBarController.showMessage("Panes are not ready yet.");
            return null;
        }

        Path activePath = active.getCurrentPath();
        Path inactivePath = inactive.getCurrentPath();
        if (activePath == null || inactivePath == null) {
            statusBarController.showMessage("Please navigate both panes first.");
            return null;
        }

        List<Path> selection = active.getSelectedPathsForOperations();
        return new CommandContext(
                activePath,
                inactivePath,
                new SelectionSnapshot(selection),
                new CancellationToken(),
                ProgressSink.NO_OP
        );
    }

    private FilePaneController mountFilePane(VBox target, String paneId, String title) throws IOException {
        FXMLLoader loader = new FXMLLoader(getClass().getResource("/com/github/uscexp/jfilework/ui/javafx/file-pane.fxml"));
        Parent paneRoot = loader.load();
        FilePaneController controller = loader.getController();
        controller.configure(paneId, title, fileService, this::updateStatus);

        target.getChildren().setAll(paneRoot);
        target.focusedProperty().addListener((obs, oldV, focused) -> {
            if (focused) {
                activePaneTracker.setActivePane("left".equals(paneId)
                        ? ActivePaneTracker.PaneSide.LEFT
                        : ActivePaneTracker.PaneSide.RIGHT);
                statusBarController.showMessage("Active pane: " + activePaneTracker.getActivePane());
            }
        });

        Node table = controller.getFileTable();
        table.focusedProperty().addListener((obs, oldV, focused) -> {
            if (focused) {
                activePaneTracker.setActivePane("left".equals(paneId)
                        ? ActivePaneTracker.PaneSide.LEFT
                        : ActivePaneTracker.PaneSide.RIGHT);
            }
        });

        return controller;
    }

    private Path resolveStartPath(String propertyKey, String configuredUiPath) {
        String configuredPath = System.getProperty(propertyKey);
        if (configuredPath != null && !configuredPath.isBlank()) {
            Path path = Paths.get(configuredPath.trim());
            if (fileService.exists(path) && fileService.isDirectory(path)) {
                return path;
            }
            log.warn("Configured start path '{}' is invalid for {}", configuredPath, propertyKey);
        }

        if (configuredUiPath != null && !configuredUiPath.isBlank()) {
            Path path = Paths.get(configuredUiPath.trim());
            if (fileService.exists(path) && fileService.isDirectory(path)) {
                return path;
            }
            log.warn("Configured UI start path '{}' is invalid for {}", configuredUiPath, propertyKey);
        }

        return Paths.get(System.getProperty("user.home"));
    }

    private void updateStatus(String message) {
        statusBarController.showMessage(message);
    }
}

package com.github.uscexp.jfilework.ui.javafx;

import javafx.scene.control.Button;
import org.junit.jupiter.api.BeforeAll;
import org.junit.jupiter.api.Tag;
import org.junit.jupiter.api.Test;

import java.nio.file.Path;

import static org.junit.jupiter.api.Assertions.assertTrue;

@Tag("ui")
class DisabledActionUiTest extends MainWindowUiTestBase {

    @BeforeAll
    static void useInvalidCommandConfig() throws Exception {
        String config = """
                {
                  "ui": { "theme": "system", "showHiddenFiles": false, "leftStartPath": "", "rightStartPath": "" },
                  "actions": [
                    {
                      "id": "brokenAction",
                      "label": "Broken Action",
                      "commandId": "missing.command",
                      "params": {},
                      "shortcut": "",
                      "placement": ["toolbar.main"]
                    }
                  ]
                }
                """;
        Path configPath = writeConfigFile("jfilework-m3-disabled", config);
        System.setProperty("jfilework.config", configPath.toString());
    }

    @Test
    void unknownCommandActionIsDisabledInToolbar() {
        Button button = lookup("#action-brokenAction").queryAs(Button.class);
        assertTrue(button.isDisable(), "Expected toolbar action to be disabled for unknown command");
    }
}

package com.github.uscexp.jfilework.ui.javafx;

import com.github.uscexp.jfilework.ui.javafx.model.FileItemViewModel;
import javafx.scene.control.TableView;
import javafx.scene.input.KeyCode;
import org.junit.jupiter.api.BeforeAll;
import org.junit.jupiter.api.Tag;
import org.junit.jupiter.api.Test;
import org.testfx.util.WaitForAsyncUtils;

import java.nio.file.Path;
import java.util.concurrent.TimeUnit;

import static org.junit.jupiter.api.Assertions.assertTrue;

@Tag("ui")
class HotkeyBindingUiTest extends MainWindowUiTestBase {

    @BeforeAll
    static void useHotkeyConfig() throws Exception {
        String config = """
                {
                  "ui": { "theme": "system", "showHiddenFiles": false, "leftStartPath": "", "rightStartPath": "" },
                  "actions": [
                    {
                      "id": "copyByF9",
                      "label": "Copy with F9",
                      "commandId": "file.copy",
                      "params": { "target": "${inactivePane.path}" },
                      "shortcut": "F9",
                      "placement": ["menu.tools"]
                    }
                  ]
                }
                """;
        Path configPath = writeConfigFile("jfilework-m3-hotkey", config);
        System.setProperty("jfilework.config", configPath.toString());
    }

    @Test
    void configuredHotkeyTriggersCommandWithoutMouse() {
        clickOn("#leftFileTable");
        clickOn("alpha.txt");
        push(KeyCode.F9);

        WaitForAsyncUtils.sleep(500, TimeUnit.MILLISECONDS);

        TableView<FileItemViewModel> rightTable = lookup("#rightFileTable").queryTableView();
        boolean containsCopiedFile = rightTable.getItems().stream()
                .anyMatch(item -> "alpha.txt".equals(item.getName()));
        assertTrue(containsCopiedFile, "Expected alpha.txt copied via configured F9 hotkey");
    }
}

